st.markdown("""
<style>
/* Ajustes visuales v.013: logo compacto, pictogramas reales y selección amarilla. */
.mg-topbar{grid-template-columns:1fr!important;padding:10px 18px!important;min-height:78px}
.mg-brand{gap:14px!important}
.mg-brand img{
  display:block!important;width:220px!important;height:74px!important;max-width:38vw!important;
  object-fit:contain!important;object-position:center!important;flex:0 0 auto!important;
  padding:4px!important;background:#fff!important;border-radius:13px!important;
  box-shadow:0 2px 12px #0008!important
}
.mg-brand-copy{border-left:2px solid #777!important;padding-left:14px!important}
.mg-brand-copy strong{font-size:1.2rem!important}
.mg-brand-copy small{font-size:.66rem!important}
div[class*="st-key-mod_"] [data-testid="stButton"]>button{
  justify-content:flex-start!important;text-align:left!important;
  color:#fff!important;background:linear-gradient(115deg,#202223,#111213)!important;
  border:1px solid #414141!important;padding:13px 18px!important;min-height:94px!important;
}
div[class*="st-key-mod_"] [data-testid="stButton"]>button>div{
  justify-content:flex-start!important;text-align:left!important;gap:13px!important
}
div[class*="st-key-mod_"] [data-testid="stButton"]>button p{
  text-align:left!important;color:inherit!important;white-space:pre-line!important
}
/* Los pictogramas SVG propios se muestran en el pseudo-elemento de cada tarjeta. */
div[class*="st-key-mod_"] [data-testid="stButton"]>button:before{
  content:" "!important;display:block!important;flex:0 0 62px!important;
  width:62px!important;min-width:62px!important;height:62px!important;
  background-repeat:no-repeat!important;background-position:center!important;
  background-size:contain!important;border:0!important;border-radius:0!important;
}
div[class*="st-key-mod_"] [data-testid="stButton"]>button span:first-child,
div[class*="st-key-mod_"] [data-testid="stButton"]>button svg{
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  font-size:2.15rem!important;width:52px!important;min-width:52px!important;height:52px!important;
  transform-origin:center!important;filter:drop-shadow(0 0 8px #ffd60099);
  animation:mg-icon-bounce 1.15s ease-in-out infinite!important
}
@keyframes mg-icon-bounce{
  0%,100%{transform:translateY(0) rotate(0) scale(1)}
  25%{transform:translateY(-9px) rotate(-10deg) scale(1.18)}
  50%{transform:translateY(1px) rotate(8deg) scale(1.04)}
  75%{transform:translateY(-5px) rotate(0) scale(1.12)}
}
/* Variación visible por módulo, aplicada al icono nativo. */
div[class*="st-key-mod_checklist_pre"] button span:first-child{animation-name:mg-icon-tilt!important}
div[class*="st-key-mod_emergencias"] button span:first-child{animation-name:mg-icon-alarm!important}
div[class*="st-key-mod_horario"] button span:first-child{animation-name:mg-icon-spin!important}
div[class*="st-key-mod_capacitaciones"] button span:first-child{animation-name:mg-icon-books!important}
@keyframes mg-icon-tilt{0%,100%{transform:rotate(0) scale(1)}25%{transform:rotate(-16deg) scale(1.18)}50%{transform:rotate(13deg) scale(1.1)}75%{transform:rotate(-8deg) scale(1.14)}}
@keyframes mg-icon-alarm{0%,100%{transform:rotate(0) scale(1)}20%{transform:rotate(-20deg) scale(1.2)}40%{transform:rotate(20deg) scale(1.18)}60%{transform:rotate(-14deg) scale(1.2)}}
@keyframes mg-icon-spin{to{transform:rotate(360deg)}}
@keyframes mg-icon-books{0%,100%{transform:translateY(0) rotate(0)}30%{transform:translateY(-10px) rotate(10deg)}60%{transform:translateY(2px) rotate(-8deg)}}
div[class*="st-key-mod_"] [data-testid="stButton"]>button:hover,
div[class*="st-key-mod_"] [data-testid="stButton"]>button:focus,
div[class*="st-key-mod_"] [data-testid="stButton"]>button:focus-visible,
div[class*="st-key-mod_"] [data-testid="stButton"]>button:active{
  background:linear-gradient(120deg,#ffe84a,#ffd000)!important;
  color:#080808!important;border:2px solid #ffe84a!important;
  box-shadow:0 0 0 2px #ffd60055,0 0 28px #ffd60055!important;
  outline:none!important;transform:translateY(-2px)!important
}
div[class*="st-key-mod_"] [data-testid="stButton"]>button:hover p,
div[class*="st-key-mod_"] [data-testid="stButton"]>button:focus p,
div[class*="st-key-mod_"] [data-testid="stButton"]>button:active p{color:#080808!important}
div[class*="st-key-mod_"] [data-testid="stButton"]>button:disabled{
  background:linear-gradient(115deg,#1b1b1b,#101010)!important;color:#aaa!important;
  border-color:#333!important;box-shadow:none!important;transform:none!important
}
@media(max-width:760px){
 .mg-topbar{padding:9px 10px!important}
 .mg-brand img{width:145px!important;height:48px!important;max-width:42vw!important}
 div[class*="st-key-mod_"] [data-testid="stButton"]>button{min-height:82px!important;padding:9px 10px!important}
 div[class*="st-key-mod_"] [data-testid="stButton"]>button span:first-child,
 div[class*="st-key-mod_"] [data-testid="stButton"]>button svg{width:42px!important;min-width:42px!important;height:42px!important;font-size:1.75rem!important}
}
</style>
""", unsafe_allow_html=True)


